#!/usr/bin/env python3
"""run-dev-graph-init executor: idempotent, fail-closed caller-repo initialization.

Implements the SKILL execution contract:
  1. C24 resolve-repo-context.py --mode write  (content authority)
  2. preview existing files, create missing 6 content roots + repo-local dirs
  3. idempotent template scaffold from the plugin (never overwrite user edits)
  4. plugin hook default; project fallback only when allowed (never here)
  5. validate-graph-schema.py gate + second-run planned_changes == 0
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

PLUGIN_ROOT = Path("/Users/dm/dev/dev/個人開発/harness/plugins/dev-graph")
sys.path.insert(0, str(PLUGIN_ROOT / "scripts"))
from _common import ContractError, atomic_json, contained, load_json, utc_now  # noqa: E402

SCRIPTS = PLUGIN_ROOT / "scripts"
CONTENT_ROOTS = {
    "issues": "issues",
    "tasks": "tasks",
    "specifications": "specs",
    "architecture": "architecture",
    "features": "features",
    "documents": "docs",
    "system_spec": "system-spec",
}
SIX_CONTENT_ROOTS = ["issues", "tasks", "specs", "architecture", "features", "docs"]
LOCAL_STATE = {
    "graph": ".dev-graph/state/graph.json",
    "cache": ".dev-graph/cache",
    "locks": ".dev-graph/locks",
}
GRAPH_ALIAS = ".dev-graph/graph.json"  # in-repo relative symlink to local_state.graph
TEMPLATES_DIR = ".dev-graph/templates"
INITIAL_GRAPH = {"schema_version": "1.0.0", "graph_revision": 0, "nodes": []}
HOOK_EVENTS = ("PreToolUse", "SessionStart", "PostToolUse", "TaskCompleted")
SECRET_SUBSTRINGS = ("token", "secret", "password", "credential", "apikey", "api_key")
SECRET_WORDS = {"pat", "auth", "key", "authorization", "bearer"}
NODE_ID_PREFIXES = ("PVT_", "PVTI_", "PVTF_", "PVTSSF_", "I_kw", "MDU6", "MDEx", "PR_kw", "R_kg")


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def run(argv: list[str]) -> subprocess.CompletedProcess[str]:
    return subprocess.run(argv, text=True, capture_output=True, check=False)


def resolve_context(repo_root: str) -> dict[str, Any]:
    cp = run([sys.executable, str(SCRIPTS / "resolve-repo-context.py"),
              "--repo-root", repo_root, "--mode", "write"])
    if cp.returncode != 0:
        raise ContractError(f"C24 context resolution failed: {cp.stderr.strip()}")
    receipt = json.loads(cp.stdout)
    root = Path(receipt["repo_root"]).resolve(strict=True)
    if Path(receipt["content_roots"]["repository"]).resolve(strict=True) != root:
        raise ContractError("content authority does not match resolved repo root")
    if Path(receipt["plugin_source"]).resolve(strict=True) == root:
        raise ContractError("plugin source must not be the content authority")
    return receipt


def repo_slug(root: Path) -> str:
    cp = run(["git", "-C", str(root), "remote", "get-url", "origin"])
    remote = cp.stdout.strip() if cp.returncode == 0 else ""
    match = re.fullmatch(
        r"(?:https?://github\.com/|ssh://git@github\.com/|git@github\.com:)([^/]+)/(.+?)(?:\.git)?/?",
        remote, re.IGNORECASE)
    if match:
        return f"{match.group(1)}/{match.group(2)}"
    return f"local/{root.name}"


def beads_prefix(root: Path) -> str:
    candidate = re.sub(r"[^a-z0-9-]+", "-", root.name.lower()).strip("-")
    if not candidate or not candidate[0].isalpha():
        candidate = f"dg-{candidate}" if candidate else "dev-graph"
    return candidate


def desired_config(receipt: dict[str, Any], root: Path, hook_source: str) -> dict[str, Any]:
    return {
        "schema_version": "1.0.0",
        "repository_id": receipt["repository_id"],
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "github": {
            "enabled": False,
            "issue_repository": repo_slug(root),
            "projects": [{
                "alias": "delivery",
                "owner_type": "user",
                "owner_login": repo_slug(root).split("/")[0],
                "project_number": 1,
                "default": True,
                "auto_add": {
                    "artifact_kinds": ["task"],
                    "confirmation_status": "confirmed",
                    "evaluation_status": "pass",
                    "implementation_readiness": "complete",
                },
                "field_mappings": [
                    {"local_field": "status", "project_field_name": "Status",
                     "value_type": "single_select", "direction": "local_to_project",
                     "option_map": {"active": "In Progress", "blocked": "Blocked", "done": "Done"}},
                    {"local_field": "priority", "project_field_name": "Priority",
                     "value_type": "single_select", "direction": "bidirectional",
                     "option_map": {"high": "High", "medium": "Medium", "low": "Low"}},
                ],
            }],
            "completion_policy": {
                "trigger": "linked_pr_merged",
                "required_pull_requests": "all",
                "target_branch": "default",
                "closed_unmerged": "keep_active",
                "issue_reopened": "reopen_task",
                "revert": "create_follow_up_unless_issue_reopened",
                "local_reconciliation": ["manual_sync", "claude_hook", "scheduled_sync"],
                "scheduled_reconciliation": {
                    "enabled": True, "interval_minutes": 5,
                    "owner": "claude_session_start",
                    "entry_point": "dev-graph sync --reconcile-lifecycle",
                },
            },
        },
        "execution_tracker": {
            "mode": "beads",
            "beads": {"issue_prefix": beads_prefix(root), "server_mode": False,
                      "github_mirror": "bd_github_push_only", "board": "static-render"},
        },
        "worktrees": {
            "enabled": True, "lease_ttl_seconds": 1800, "heartbeat_seconds": 60,
            "coordination_store": "git_common_dir", "completion_write_branch": "default",
            "dirty_worktree_policy": "fail_closed",
        },
        "claude_hooks": {
            "source": hook_source,
            "project_plugin_link": ".claude/dev-graph-plugin",
            "session_start": True, "post_tool_reconcile": True, "task_completed_gate": True,
        },
        "path_policy": {
            "authority": "caller-repository", "stored_paths": "repository-relative",
            "allow_outside_repository": False,
            "follow_content_symlinks_outside_repository": False,
        },
    }


def config_hygiene(config: Any, root: Path) -> list[str]:
    """Reject absolute paths, secrets and GitHub node IDs anywhere in the config."""
    home = str(Path.home())
    findings: list[str] = []

    def walk(value: Any, path: str) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                lowered = str(key).lower()
                words = set(re.split(r"[^a-z0-9]+", lowered))
                if any(hint in lowered for hint in SECRET_SUBSTRINGS) or (words & SECRET_WORDS):
                    findings.append(f"secret-like key at {path}.{key}")
                walk(child, f"{path}.{key}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, f"{path}[{index}]")
        elif isinstance(value, str):
            if value.startswith("/") or value.startswith("~") or home in value or str(root) in value:
                findings.append(f"absolute path at {path}: {value}")
            if any(value.startswith(prefix) for prefix in NODE_ID_PREFIXES):
                findings.append(f"github node id at {path}")
            if re.fullmatch(r"gh[pousr]_[A-Za-z0-9]{20,}", value):
                findings.append(f"token-like value at {path}")

    walk(config, "$")
    return findings


def validate_config_schema(config: dict[str, Any]) -> list[str]:
    schema = load_json(PLUGIN_ROOT / "schemas" / "repo-config.schema.json")
    try:
        from jsonschema import Draft202012Validator  # type: ignore
    except ImportError:
        sys.path.insert(0, str(SCRIPTS))
        module = __import__("importlib").import_module("importlib.util")
        spec = module.spec_from_file_location("vgs", SCRIPTS / "validate-graph-schema.py")
        vgs = module.module_from_spec(spec)
        spec.loader.exec_module(vgs)  # type: ignore[union-attr]
        return [f"{p}: {d}" for p, d in vgs._schema_fallback(config, schema, schema)]
    return [f"{'.'.join(str(x) for x in e.absolute_path)}: {e.message}"
            for e in sorted(Draft202012Validator(schema).iter_errors(config),
                            key=lambda e: (tuple(str(p) for p in e.absolute_path), e.message))]


def plugin_templates() -> list[Path]:
    return sorted(p for p in (PLUGIN_ROOT / "templates").iterdir() if p.is_file())


def hook_diagnostics(root: Path, hook_source: str) -> dict[str, Any]:
    manifest = PLUGIN_ROOT / "hooks" / "hooks.json"
    if not manifest.is_file():
        raise ContractError("plugin hook manifest is missing")
    events = sorted((load_json(manifest).get("hooks") or {}).keys())
    if set(events) != set(HOOK_EVENTS):
        raise ContractError(f"plugin hook manifest does not cover C10/C25 events: {events}")
    settings = root / ".claude" / "settings.json"
    project_events: list[str] = []
    if settings.is_file():
        data = load_json(settings)
        for event, entries in ((data.get("hooks") or {}) if isinstance(data, dict) else {}).items():
            blob = json.dumps(entries, ensure_ascii=False)
            if "dev-graph" in blob:
                project_events.append(event)
    double = sorted(set(project_events) & set(events))
    return {
        "requested_source": hook_source,
        "effective_source": "plugin" if hook_source == "plugin" else hook_source,
        "plugin_hook_manifest": "hooks/hooks.json",
        "plugin_hook_events": events,
        "project_settings_present": settings.is_file(),
        "project_dev_graph_hook_events": sorted(project_events),
        "double_registration_paths": double,
        "project_fallback_applied": False,
        "project_fallback_rejected_reason": (
            "effective plugin hook manifest is present; project-fallback is only allowed for "
            "plain-symlink installs without an effective plugin hook"
        ),
        "settings_write_count": 0,
        "rollback_manifest": None,
    }


def plan_and_apply(root: Path, receipt: dict[str, Any], hook_source: str, apply: bool) -> dict[str, Any]:
    planned: list[str] = []
    created: list[str] = []
    preserved: list[str] = []
    migration_preview: list[dict[str, str]] = []

    def ensure_dir(relative: str) -> None:
        target = contained(root / relative, root, must_exist=False)
        if target.is_dir() and not target.is_symlink():
            preserved.append(f"dir:{relative}")
            return
        if target.exists() or target.is_symlink():
            raise ContractError(f"expected directory is occupied by another node: {relative}")
        planned.append(f"dir:{relative}")
        if apply:
            target.mkdir(parents=True)
            created.append(f"dir:{relative}")

    for relative in SIX_CONTENT_ROOTS + [CONTENT_ROOTS["system_spec"]]:
        ensure_dir(relative)
    for relative in [".dev-graph", ".dev-graph/state", LOCAL_STATE["cache"],
                     LOCAL_STATE["locks"], TEMPLATES_DIR]:
        ensure_dir(relative)

    # config.json: create when missing, preserve user-owned content otherwise.
    config_relative = ".dev-graph/config.json"
    config_path = root / config_relative
    wanted = desired_config(receipt, root, hook_source)
    if config_path.is_file() and not config_path.is_symlink():
        existing = load_json(config_path)
        preserved.append(f"file:{config_relative}")
        if existing.get("repository_id") != receipt["repository_id"]:
            raise ContractError("existing config repository_id does not match resolved repository")
        if existing != wanted:
            migration_preview.append({
                "path": config_relative, "reason": "user_edited",
                "existing_digest": sha256_file(config_path),
                "plugin_default_digest": sha256_text(
                    json.dumps(wanted, ensure_ascii=False, sort_keys=True, indent=2) + "\n"),
            })
        config = existing
    else:
        planned.append(f"file:{config_relative}")
        config = wanted
        if apply:
            atomic_json(config_path, wanted)
            created.append(f"file:{config_relative}")

    # graph store + in-repo relative alias
    graph_relative = LOCAL_STATE["graph"]
    graph_path = root / graph_relative
    if graph_path.is_file() and not graph_path.is_symlink():
        preserved.append(f"file:{graph_relative}")
    else:
        planned.append(f"file:{graph_relative}")
        if apply:
            atomic_json(graph_path, INITIAL_GRAPH)
            created.append(f"file:{graph_relative}")
    alias = root / GRAPH_ALIAS
    if alias.is_symlink():
        if os.readlink(alias) != "state/graph.json":
            raise ContractError(f"graph alias points elsewhere: {os.readlink(alias)}")
        contained(alias, root)
        preserved.append(f"symlink:{GRAPH_ALIAS}")
    elif alias.exists():
        preserved.append(f"file:{GRAPH_ALIAS}")
    else:
        planned.append(f"symlink:{GRAPH_ALIAS}")
        if apply:
            alias.symlink_to("state/graph.json")
            created.append(f"symlink:{GRAPH_ALIAS}")

    # templates: copy missing only; never overwrite user-edited files
    templates_created, templates_preserved, templates_edited = [], [], []
    for source in plugin_templates():
        relative = f"{TEMPLATES_DIR}/{source.name}"
        target = root / relative
        if target.is_symlink():
            raise ContractError(f"template must not be a symlink: {relative}")
        if target.is_file():
            digest, plugin_digest = sha256_file(target), sha256_file(source)
            if digest == plugin_digest:
                templates_preserved.append(source.name)
            else:
                templates_edited.append(source.name)
                migration_preview.append({
                    "path": relative, "reason": "user_edited",
                    "existing_digest": digest, "plugin_default_digest": plugin_digest,
                })
            preserved.append(f"template:{source.name}")
        else:
            planned.append(f"template:{source.name}")
            if apply:
                target.write_bytes(source.read_bytes())
                created.append(f"template:{source.name}")
                templates_created.append(source.name)

    contract = load_json(PLUGIN_ROOT / "templates" / "template-contract.json")
    required = {contract["common_frontmatter"]["template"], "template-contract.json"}
    for entry in contract["artifacts"].values():
        required.add(entry["template"])
        for name in (entry.get("subtype_templates") or {}).values():
            required.add(name)
        for name in (entry.get("conditional_templates") or {}).values():
            required.add(name)
    required.add(contract["graph_projection"]["template"])
    required.add(contract["system_plan"]["task_overlay"])
    present = {p.name for p in (root / TEMPLATES_DIR).iterdir() if p.is_file()} if (root / TEMPLATES_DIR).is_dir() else set()
    missing = sorted(required - present)

    hooks = hook_diagnostics(root, hook_source)

    failures: list[str] = []
    hygiene = config_hygiene(config, root)
    if hygiene:
        failures.append("config hygiene violation")
    schema_errors = validate_config_schema(config) if apply else []
    if schema_errors:
        failures.append("repo-config schema violation")
    if apply and missing:
        failures.append("template contract asset missing")
    if hooks["double_registration_paths"]:
        failures.append("double hook registration")

    gate: dict[str, Any] = {"ran": False}
    if apply:
        cp = run([sys.executable, str(SCRIPTS / "validate-graph-schema.py"),
                  "--graph", str(root / graph_relative), "--repo-root", str(root)])
        gate = {"ran": True, "exit_code": cp.returncode,
                "report": json.loads(cp.stdout) if cp.stdout.strip() else None,
                "stderr": cp.stderr.strip()}
        if cp.returncode != 0:
            failures.append("C11 graph schema gate failed")

    return {
        "generated_at": utc_now(),
        "mode": "apply" if apply else "preview",
        "repository_id": receipt["repository_id"],
        "worktree_id": receipt["worktree_id"],
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "planned_changes": sorted(planned),
        "planned_change_count": len(planned),
        "created": sorted(created),
        "preserved": sorted(preserved),
        "migration_preview": migration_preview,
        "templates": {
            "created": sorted(templates_created), "preserved": sorted(templates_preserved),
            "user_edited": sorted(templates_edited), "missing_contract_assets": missing,
            "total_plugin_templates": len(plugin_templates()),
        },
        "hooks": hooks,
        "config_hygiene_findings": hygiene,
        "config_schema_errors": schema_errors,
        "schema_result": gate,
        "status": "FAIL" if failures else "PASS",
        "failures": failures,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--hook-source", default="plugin", choices=("plugin", "project-fallback"))
    parser.add_argument("--preview-only", action="store_true")
    parser.add_argument("--receipt-out")
    args = parser.parse_args()
    receipt = resolve_context(args.repo_root)
    root = Path(receipt["repo_root"]).resolve(strict=True)
    hook_source = "plugin" if args.hook_source == "plugin" else "project"
    if args.hook_source == "project-fallback":
        raise ContractError("project-fallback is rejected while an effective plugin hook is present")
    preview = plan_and_apply(root, receipt, hook_source, apply=False)
    result = preview if args.preview_only else plan_and_apply(root, receipt, hook_source, apply=True)
    result["preview_planned_changes"] = preview["planned_changes"]
    result["context_receipt"] = {
        "repository_id": receipt["repository_id"], "worktree_id": receipt["worktree_id"],
        "root_trust_evidence": receipt["root_trust_evidence"],
        "diagnostics": receipt["diagnostics"],
    }
    if args.receipt_out:
        atomic_json(Path(args.receipt_out), result)
    print(json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2))
    return 0 if result["status"] == "PASS" else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(2)

