        r"(?:https?://github\.com/|ssh://git@github\.com/|git@github\.com:)([^/]+)/(.+?)(?:\.git)?/?",
        remote, re.IGNORECASE)
    if match:
        return f"{match.group(1)}/{match.group(2)}"
