            atomic_json(graph_path, INITIAL_GRAPH)
            created.append(f"file:{graph_relative}")
    alias = root / GRAPH_ALIAS
    if alias.is_symlink():
        if os.readlink(alias) != "state/graph.json":
            raise ContractError(f"graph alias points elsewhere: {os.readlink(alias)}")
        contained(alias, root)
        preserved.append(f"symlink:{GRAPH_ALIAS}")
    elif alias.exists():
        preserved.append(f"file:{GRAPH_ALIAS}")
    else:
        planned.append(f"symlink:{GRAPH_ALIAS}")
        if apply:
            alias.symlink_to("state/graph.json")
            created.append(f"symlink:{GRAPH_ALIAS}")

    # templates: copy missing only; never overwrite user-edited files
    templates_created, templates_preserved, templates_edited = [], [], []
    for source in plugin_templates():
        relative = f"{TEMPLATES_DIR}/{source.name}"
        target = root / relative
        if target.is_symlink():
            raise ContractError(f"template must not be a symlink: {relative}")
        if target.is_file():
            digest, plugin_digest = sha256_file(target), sha256_file(source)
            if digest == plugin_digest:
                templates_preserved.append(source.name)
            else:
                templates_edited.append(source.name)
                migration_preview.append({
                    "path": relative, "reason": "user_edited",
                    "existing_digest": digest, "plugin_default_digest": plugin_digest,
                })
            preserved.append(f"template:{source.name}")
        else:
            planned.append(f"template:{source.name}")
            if apply:
                target.write_bytes(source.read_bytes())
                created.append(f"template:{source.name}")
                templates_created.append(source.name)

    contract = load_json(PLUGIN_ROOT / "templates" / "template-contract.json")
    required = {contract["common_frontmatter"]["template"], "template-contract.json"}
    for entry in contract["artifacts"].values():
        required.add(entry["template"])
        for name in (entry.get("subtype_templates") or {}).values():
            required.add(name)
        for name in (entry.get("conditional_templates") or {}).values():
            required.add(name)
    required.add(contract["graph_projection"]["template"])
    required.add(contract["system_plan"]["task_overlay"])
    present = {p.name for p in (root / TEMPLATES_DIR).iterdir() if p.is_file()} if (root / TEMPLATES_DIR).is_dir() else set()
    missing = sorted(required - present)

    hooks = hook_diagnostics(root, hook_source)

    failures: list[str] = []
    hygiene = config_hygiene(config, root)
    if hygiene:
        failures.append("config hygiene violation")
    schema_errors = validate_config_schema(config) if apply else []
    if schema_errors:
        failures.append("repo-config schema violation")
    if apply and missing:
        failures.append("template contract asset missing")
    if hooks["double_registration_paths"]:
        failures.append("double hook registration")

    gate: dict[str, Any] = {"ran": False}
    if apply:
        cp = run([sys.executable, str(SCRIPTS / "validate-graph-schema.py"),
                  "--graph", str(root / graph_relative), "--repo-root", str(root)])
        gate = {"ran": True, "exit_code": cp.returncode,
                "report": json.loads(cp.stdout) if cp.stdout.strip() else None,
                "stderr": cp.stderr.strip()}
        if cp.returncode != 0:
            failures.append("C11 graph schema gate failed")

    return {
        "generated_at": utc_now(),
        "mode": "apply" if apply else "preview",
        "repository_id": receipt["repository_id"],
        "worktree_id": receipt["worktree_id"],
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "planned_changes": sorted(planned),
        "planned_change_count": len(planned),
        "created": sorted(created),
        "preserved": sorted(preserved),
        "migration_preview": migration_preview,
        "templates": {
            "created": sorted(templates_created), "preserved": sorted(templates_preserved),
            "user_edited": sorted(templates_edited), "missing_contract_assets": missing,
            "total_plugin_templates": len(plugin_templates()),
        },
        "hooks": hooks,
        "config_hygiene_findings": hygiene,
        "config_schema_errors": schema_errors,
        "schema_result": gate,
        "status": "FAIL" if failures else "PASS",
        "failures": failures,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--hook-source", default="plugin", choices=("plugin", "project-fallback"))
    parser.add_argument("--preview-only", action="store_true")
    parser.add_argument("--receipt-out")
    args = parser.parse_args()
    receipt = resolve_context(args.repo_root)
    root = Path(receipt["repo_root"]).resolve(strict=True)
    hook_source = "plugin" if args.hook_source == "plugin" else "project"
    if args.hook_source == "project-fallback":
        raise ContractError("project-fallback is rejected while an effective plugin hook is present")
    preview = plan_and_apply(root, receipt, hook_source, apply=False)
    result = preview if args.preview_only else plan_and_apply(root, receipt, hook_source, apply=True)
    result["preview_planned_changes"] = preview["planned_changes"]
    result["context_receipt"] = {
        "repository_id": receipt["repository_id"], "worktree_id": receipt["worktree_id"],
        "root_trust_evidence": receipt["root_trust_evidence"],
        "diagnostics": receipt["diagnostics"],
    }
    if args.receipt_out:
        atomic_json(Path(args.receipt_out), result)
    print(json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2))
    return 0 if result["status"] == "PASS" else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(2)

